//! Interoperability fixtures generated by the official zstd v1.5.7 executable.
//! The input data is original and generated deterministically below. See
//! `tests/fixtures/README.md` for regeneration commands and provenance.

use std::io::Write;
use std::process::{Command, Stdio};

use zstdoxide::decompress;

fn random_values(count: usize) -> impl Iterator<Item = u64> {
    let mut state = 0x4d59_5df4_d0f3_3173u64;
    (0..count).map(move |_| {
        state ^= state << 13;
        state ^= state >> 7;
        state ^= state << 17;
        state
    })
}

fn corpus(name: &str) -> Vec<u8> {
    match name {
        "empty" => Vec::new(),
        "tiny" => b"Safe Rust, explicit ownership, checked decoding.\n".to_vec(),
        "runs" => vec![b'r'; 300_000],
        "random" => random_values(4096).map(|value| (value >> 24) as u8).collect(),
        "skewed" => random_values(64_000)
            .map(|value| b'a' + value.trailing_zeros().min(7) as u8)
            .collect(),
        "text" => (0..4096)
            .flat_map(|index| {
                format!(
                    "record {index:05}: safe Rust keeps ownership explicit; repeated tokens compress well; group={}.\n",
                    index % 17
                )
                .into_bytes()
            })
            .collect(),
        "history" => {
            let block: Vec<_> = random_values(65536).map(|value| (value >> 24) as u8).collect();
            let mut output = Vec::new();
            for _ in 0..5 {
                output.extend_from_slice(&block);
                output.extend_from_slice(b"|history-window|");
            }
            output
        }
        _ => panic!("unknown corpus {name}"),
    }
}

const FIXTURES: &[(&str, &str, &[u8])] = &[
    ("empty-3", "empty", include_bytes!("fixtures/empty-3.zst")),
    ("tiny-1", "tiny", include_bytes!("fixtures/tiny-1.zst")),
    ("runs-3", "runs", include_bytes!("fixtures/runs-3.zst")),
    (
        "random-3",
        "random",
        include_bytes!("fixtures/random-3.zst"),
    ),
    (
        "skewed-3",
        "skewed",
        include_bytes!("fixtures/skewed-3.zst"),
    ),
    (
        "skewed-19",
        "skewed",
        include_bytes!("fixtures/skewed-19.zst"),
    ),
    ("text-1", "text", include_bytes!("fixtures/text-1.zst")),
    ("text-3", "text", include_bytes!("fixtures/text-3.zst")),
    ("text-9", "text", include_bytes!("fixtures/text-9.zst")),
    ("text-19", "text", include_bytes!("fixtures/text-19.zst")),
    (
        "history-9",
        "history",
        include_bytes!("fixtures/history-9.zst"),
    ),
    (
        "text-unknown-size",
        "text",
        include_bytes!("fixtures/text-unknown-size.zst"),
    ),
];

#[test]
fn decodes_official_frames_at_multiple_levels() {
    for &(fixture, name, encoded) in FIXTURES {
        let expected = corpus(name);
        let actual = decompress(encoded, expected.len())
            .unwrap_or_else(|error| panic!("{fixture}: {error:?}"));
        assert_eq!(actual, expected, "fixture {fixture}");
    }
}

#[test]
fn rejects_truncated_official_frames_and_output_limit_overruns() {
    for &(fixture, name, encoded) in FIXTURES {
        let expected = corpus(name);
        for end in (1..encoded.len().min(12)).chain(encoded.len().saturating_sub(16)..encoded.len())
        {
            if end != 0 {
                assert!(
                    decompress(&encoded[..end], expected.len()).is_err(),
                    "{fixture} was accepted after truncation at {end}"
                );
            }
        }
        if !expected.is_empty() {
            assert!(
                decompress(encoded, expected.len() - 1).is_err(),
                "{fixture} exceeded the output limit"
            );
        }
    }
}

#[test]
fn verifies_checksums_on_official_frames() {
    for &(fixture, name, encoded) in FIXTURES {
        if fixture == "text-unknown-size" {
            continue;
        }
        let mut changed = encoded.to_vec();
        let last = changed.len() - 1;
        changed[last] ^= 0x80;
        assert!(
            decompress(&changed, corpus(name).len()).is_err(),
            "{fixture} accepted an altered checksum"
        );
    }
}

#[test]
fn decodes_concatenated_and_skippable_official_frames() {
    let mut encoded = Vec::new();
    let mut expected = Vec::new();
    for &(fixture, name, frame) in &FIXTURES[..5] {
        // All sixteen skippable magic values share the same header contract.
        let magic = 0x184d_2a50u32 + ((fixture.len() as u32) & 15);
        encoded.extend_from_slice(&magic.to_le_bytes());
        encoded.extend_from_slice(&(fixture.len() as u32).to_le_bytes());
        encoded.extend_from_slice(fixture.as_bytes());
        encoded.extend_from_slice(frame);
        expected.extend_from_slice(&corpus(name));
    }
    assert_eq!(decompress(&encoded, expected.len()).unwrap(), expected);
}

/// Invoke the CLI oracle only; production codec code never uses another codec.
fn oracle(arguments: &[String], input: &[u8]) -> Vec<u8> {
    let executable = std::env::var_os("ZSTD_BIN").unwrap_or_else(|| "zstd".into());
    let mut child = Command::new(executable)
        .args(arguments)
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .expect("install official zstd v1.5.7 or set ZSTD_BIN");
    let mut stdin = child.stdin.take().unwrap();
    // Consume stdout while input is written to avoid pipe-capacity deadlocks.
    std::thread::scope(|scope| {
        let writer = scope.spawn(move || {
            stdin.write_all(input).unwrap();
        });
        let result = child.wait_with_output().unwrap();
        writer.join().unwrap();
        assert!(
            result.status.success(),
            "oracle failed: {}",
            String::from_utf8_lossy(&result.stderr)
        );
        result.stdout
    })
}

#[test]
#[ignore = "requires the external official zstd v1.5.7 test oracle"]
fn differential_decode_against_official_cli() {
    let version = oracle(&["--version".into()], &[]);
    assert!(String::from_utf8_lossy(&version).contains("v1.5.7"));
    for name in [
        "empty", "tiny", "runs", "random", "skewed", "text", "history",
    ] {
        let source = corpus(name);
        for level in [1, 3, 9, 19] {
            for known_size in [false, true] {
                let mut arguments = vec![
                    "-q".into(),
                    "-c".into(),
                    format!("-{level}"),
                    "--check".into(),
                ];
                if known_size {
                    arguments.push(format!("--stream-size={}", source.len()));
                }
                let encoded = oracle(&arguments, &source);
                let actual = decompress(&encoded, source.len()).unwrap_or_else(|error| {
                    panic!("{name}, level {level}, known size {known_size}: {error:?}")
                });
                assert_eq!(
                    actual, source,
                    "{name}, level {level}, known size {known_size}"
                );
            }
        }
    }
}
